from taf.sbts.oam.coam.admin import admin
from robot.libraries.BuiltIn import BuiltIn

from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output


class ClassicalApiConnection:
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self):
        self._api = admin()
        self._host = None

    def connect_to(self, name, timeout=60):
        """
        Connects to Node B via admin
        :param name: name of returned connection (alias)
        :type name: str
        :param timeout: execution timeout (default 60s)
        :type timeout: int
        """
        self._connect_to(name=name, timeout=timeout)

    def disconnect(self, connection):
        """
        Disconnects and destroys node.js daemon
        :param connection: AdminConnection object or if used, string name alias
        :type connection: Union[AdminConnection, str]
        """

        self._disconnect(connection=connection)

    def get_bts_info(self, connection, timeout=10, detailed_output=False):
        """
        Gets BTS general information from Node B
        :param connection: alias with name of connection to BTS
        :type connection: Union[AdminConnection, str]
        :param timeout: keyword execution timeout (default 10s)
        :type timeout: Union[int, str]
        :param detailed_output: return full request response when True, defaults set to False
        :type detailed_output: bool

        :returns: general BTS information, part of example output:
                                            {
                                            "time": "12:05:40",
                                            "requestId": 1,
                                            "requestStatus": "completed",
                                            "requestMessage": {
                                                "id": {
                                                    "internal": "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1",
                                                    "configuration": "MRBTS-500068"
                                                },
                                                "name": "KRnD_gNB4",
                                                "mrbtsID": 500068,
                                                "nrBtsId": 1,
                                                "type": "NE type"
                                                "gNbCuType": "NSA",
                                                "coordinates": {
                                                    "latitude": 375063020,
                                                    "longitude": 1270636123,
                                                    "altitude": 84
                                                }
                                            }
        :rtype: dict
        """
        return self._get_bts_info(connection=connection,
                                  timeout=timeout,
                                  detailed_output=detailed_output)

    def get_cell_specific_info(self, connection, distname, timeout=60, detailed_output=False):
        """
        Get information about specific cell, provided by M-plane
        :param connection: alias with name of connection to BTS
        :type connection: AdminConnection
        :param distname: distname of cell, i.e. "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/NRBTS_R-1/NRCELL_R-1"
        :type distname: str
        :param timeout: keyword execution timeout (default 60s)
        :type timeout: Union[int, str]
        :param detailed_output: return full request response when True, defaults set to False
        :type detailed_output: bool

        :returns: information about specific cell, part of example output:
            {
               "time": "10:55:49",
               "requestId": 1,
               "requestStatus": "completed",
               "requestMessage": {
                  "id": {
                     "internal": "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-1/LNCEL_R-1",
                     "configuration": "MRBTS-1/LNBTS-1/LNCEL-1"
                  },
                  "cellName": "LNCEL-1",
                  "globalCellId": 1,
                  "downlinkChannelBandwith": "10 MHz",
                  "uplinkChannelBandwith": "10 MHz",
                  "uplinkFrequency": 1870,
                  "downlinkFrequency": 1950,
                  "bandNumber": 2,
                  "maximumOutputPower": 39,
                  "downlinkMimoMode": "TXDiv",
                  "maximumNumberOfActiveUEs": 240,
                  "maximumBitrateDownlink": 170000,
                  "maximumBitrateUplink": 75000,
                  "counters": {
                     "activeUEs": null,
                     "successfullyAssignedRadioBearers": null
            }
        :rtype: dict
        """
        return self._api.get_cell_specific_info(connection=connection,
                                                cell_id=distname,
                                                timeout=timeout,
                                                detailed_output=detailed_output)

    def get_cells_info(self, connection, cell_type="nr", timeout=10, detailed_output=False):
        """
        Get information about all cells, provided by M-plane
        :param connection: alias with name of connection to BTS
        :type connection: AdminConnection
        :param cell_type: cell type of given RAT: "lte", "wcdma", "gsm", "nr" (default "nr")
        :type cell_type: str
        :param timeout: keyword execution timeout (default 10s)
        :type timeout: Union[int, str]
        :param detailed_output: return full request response when True, defaults set to False
        :type detailed_output: bool

        :returns: information about all cells, part of example output:
        {
          "cells": {
             "lte": [
                {
                   "id": {
                      "internal": "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/LNBTS_R-318/LNCEL_R-3183",
                      "configuration": "MRBTS-318/LNBTS-318/LNCEL-3183"
                   },
                   "cellName": "LNCEL-3183",
                   "globalCellId": 3183,
                   },
                   "carrierList": [
                      {
                         "antennaLineId": {
                            "configuration": "MRBTS-318/EQM-1/APEQM-1/RMOD-1/ANTL-5",
                            "runtime": "MRBTS-318/EQM_R-1/APEQM_R-1/RMOD_R-1/ANTL_R-5"
                         },
                         "direction": "RX"
                      }
                   ]
                ],
             "wcdma": [
                {
                   "id": {
                      "internal": "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/WNBTS_R-1/WNCEL_R-1",
                      "configuration": "MRBTS-318/WNBTS-1/WNCEL-1"
                   },
                   "cellId": 1,
                   "downlinkFrequency": "2145400000",
                   "carrierList": [
                      {
                         "antennaLineId": {
                            "configuration": "MRBTS-318/EQM-1/APEQM-1/RMOD-3/ANTL-17",
                            "runtime": "MRBTS-318/EQM_R-1/APEQM_R-1/RMOD_R-3/ANTL_R-5"
                         },
                         "direction": "TX"
                      }
                   ]
                ],
             "gsm": [],
             "nr": []
        }
        :rtype: dict
        """
        return self._api.get_cells_info(cell_type=cell_type,
                                        timeout=timeout,
                                        connection=connection,
                                        detailed_output=detailed_output)

    def get_cells_distnames(self, connection):
        """
        Gets distnames of all cells
        :param connection: alias with name of connection to BTS
        :type connection: str

        :return: list of all cells distnames
        :rtype: list(str)
        """
        return self._get_cells_distnames(connection=connection)

    def get_managed_objects(self, connection, class_name):
        """
        Gets managed objects for class given by class_name
        :param connection: alias with name of connection to BTS
        :type connection: str
        :param class_name: class for which managed objects will be returned
        :type class_name: str

        :returns: managed objects for class_name, for example:
                            [{"distName":'MRBTS-1/SMOD-1', "parameters":{"param1":"value1"}},
                                {"distName":'MRBTS-1/SMOD-2', "parameters":{"param1":"value2"}}]
        :rtype: dict
        """
        return self._get_managed_objects(connection=connection, class_name=class_name)

    def perform_parameter_recommissioning(self, dist_name, parameter, operation, value, connection):
        """
        Performs parameter recommissioning
        :param dist_name: object dist name, i.e. "MRBTS-1/LNBTS-1/LNMME-0"
        :type dist_name: str
        :param parameter: parameter name
        :type parameter: str
        :param operation: parameter operation: update/delete
        :type operation: str
        :param value: parameter value
        :type value: str
        :param connection: alias with name of connection to BTS
        :type connection: str
        """
        self._api.perform_parameter_recommissioning(dist_name=dist_name,
                                                    parameter=parameter,
                                                    operation=operation,
                                                    value=value,
                                                    connection=connection)

    def teardown_all_aliases_for_admin(self):
        self._api.teardown_all_aliases_for_admin()

    def _connect_to(self, name, timeout):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__, self._connect_to.__name__))

    def _disconnect(self, connection):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__, self._disconnect.__name__))

    def _get_cells_distnames(self, connection):
        cells_distnames = []
        cells_info = self._get_bts_info(connection=connection)["cells"]

        for cell_type, cell_list in cells_info.items():
            for cell in cell_list:
                cells_distnames.append(cell["id"]["configuration"])

        return cells_distnames

    def _get_bts_info(self, connection, timeout=10, detailed_output=False):
        return self._api.get_bts_info(connection=connection,
                                      timeout=timeout,
                                      detailed_output=detailed_output)

    def _get_managed_objects(self, connection, class_name):
        return self._api.get_managed_objects(connection=connection, class_name=class_name)


class EnbApiConnection(ClassicalApiConnection):
    def __init__(self):
        super(EnbApiConnection, self).__init__()
        self._api = admin()

    def _connect_to(self, name, timeout):
        self._api.connect_to(name=name, timeout=timeout, *self._get_details_to_login())

    def _disconnect(self, connection):
        self._api.teardown(connection=connection)

    @log_input_and_output
    def _get_details_to_login(self, enb_id=0):
        bts_host = BuiltIn().get_variable_value("${{tl.enbs[{0}].oam_ip.v4}}".format(enb_id))
        bts_port = 443
        username = "Nemuadmin"
        password = "nemuuser"

        return bts_host, bts_port, username, password


class GnbApiConnection(ClassicalApiConnection):
    def __init__(self):
        super(GnbApiConnection, self).__init__()
        self._api = admin()

    def _connect_to(self, name, timeout):
        self._api.connect_to(name=name, timeout=timeout, *self._get_details_to_login())

    def _disconnect(self, connection):
        self._api.teardown(connection=connection)

    @log_input_and_output
    def _get_details_to_login(self, gnb_id=0):
        details_to_login = BuiltIn().get_variable_value("${{tl.gnbs[{0}].cu"
                                                        ".oam_http_connection_details}}".format(gnb_id))
        return details_to_login.addr, details_to_login.port, details_to_login.username, \
            details_to_login.password
